// SkillsDark.jsx
import React, { useRef, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faReact,
  faHtml5,
  faCss3,
  faJs,
  faNodeJs,
  faGitAlt,
  faAws
} from '@fortawesome/free-brands-svg-icons';
import {
  faDatabase,
  faServer,
  faCheckCircle,
  faShieldAlt,
  faCubes
} from '@fortawesome/free-solid-svg-icons';
import CustomHook from './CustomHook';

/*
  Requirements:
  - Tailwind CSS configured in your project.
  - Font Awesome packages installed:
      npm install @fortawesome/react-fontawesome @fortawesome/free-brands-svg-icons @fortawesome/free-solid-svg-icons
*/

export default function SkillsDark() {
  const divs = useRef([]);
  const scrollTab = useRef();
  divs.current = [];
  CustomHook(scrollTab, divs);

  const summaryPoints = [
    { icon: faCheckCircle, text: 'Proficient in C++, Java, and JavaScript; strong foundation in Data Structures, Algorithms, and OOP.' },
    { icon: faCubes, text: 'Hands-on MERN Stack development — MongoDB, Express.js, React.js, Node.js with Redux & Axios.' },
    { icon: faServer, text: 'Designed and built RESTful APIs; integrated MongoDB/MySQL and Firebase (Google OAuth).' },
    { icon: faReact, text: 'Frontend focus: responsive UI/UX, state management, lazy loading, and performance optimizations.' },
    { icon: faAws, text: 'Familiar with AWS, Azure DevOps, Git & GitHub for CI/CD and deployments.' },
    { icon: faDatabase, text: 'Solid DBMS understanding and practical experience with schema design & query optimization.' },
    { icon: faShieldAlt, text: 'Solved 200+ coding problems across LeetCode, Coding Ninjas, and HackerRank.' },
    { icon: faGitAlt, text: 'Active in hackathons: Google Cloud, GFG, DevHouse, Ideal Lab — build, ship, iterate.' }
  ];

  const [listSkills] = useState([
    { name: 'C++', des: 'Data structures, algorithms, OOP, competitive programming (100+ LeetCode).', icon: faServer },
    { name: 'Java', des: 'OOP, backend logic, system design basics.', icon: faServer },
    { name: 'JavaScript', des: 'ES6+, async programming, DOM & browser APIs.', icon: faJs },
    { name: 'React.js', des: 'Component-driven UIs, Redux state management, performance optimizations.', icon: faReact },
    { name: 'Node.js / Express', des: 'RESTful APIs, middleware, auth flows, integration with DBs.', icon: faNodeJs },
    { name: 'Databases & Auth', des: 'MongoDB & MySQL; Firebase and Google OAuth implementations.', icon: faDatabase },
    { name: 'DevOps & Cloud', des: 'Git workflows, Azure DevOps basics, AWS deployments.', icon: faAws },
    { name: 'Styling', des: 'HTML5, CSS3, Tailwind CSS for accessible, mobile-first designs.', icon: faHtml5 }
  ]);

  const attachRef = (el) => {
    if (el && !divs.current.includes(el)) divs.current.push(el);
  };

  return (
    <section
      ref={scrollTab}
      className="bg-gray-900 text-gray-100 py-12 px-4 sm:px-6 lg:px-8"
      aria-label="Skills"
    >
      <div className="max-w-6xl mx-auto">
        <div ref={attachRef} className="mb-8">
          <h2 className="text-3xl font-extrabold tracking-tight">Skills</h2>
          <p className="mt-2 text-gray-400">Summary of my technical strengths and experience.</p>
        </div>

        {/* Summary Points */}
        <div ref={attachRef} className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
          {summaryPoints.map((pt, idx) => (
            <div
              key={idx}
              className="flex items-start gap-4 p-4 rounded-lg bg-gradient-to-r from-gray-800/60 to-gray-800/40 border border-gray-800 hover:scale-[1.01] transform transition duration-200"
              ref={attachRef}
            >
              <div className="mt-1">
                <div className="w-10 h-10 rounded-full bg-indigo-600/20 flex items-center justify-center text-indigo-300">
                  <FontAwesomeIcon icon={pt.icon} />
                </div>
              </div>
              <p className="text-gray-200 leading-relaxed">{pt.text}</p>
            </div>
          ))}
        </div>

        {/* Skills Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {listSkills.map((s, i) => (
            <article
              key={i}
              className="group bg-gradient-to-b from-gray-800/60 to-gray-800/40 border border-gray-800 rounded-xl p-5 hover:shadow-xl hover:translate-y-[-4px] transition-transform duration-200"
              ref={attachRef}
            >
              <div className="flex items-center gap-3">
                <div className="text-indigo-300 text-2xl w-12 h-12 flex items-center justify-center rounded-md bg-indigo-600/10 group-hover:bg-indigo-600/20 transition">
                  <FontAwesomeIcon icon={s.icon} />
                </div>
                <h3 className="text-lg font-semibold text-white">{s.name}</h3>
              </div>
              <p className="mt-3 text-gray-300 text-sm leading-relaxed">{s.des}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
